package com.smartsociety.platform.complaint; import jakarta.persistence.*; import java.util.*; @Entity @Table(name="complaint_categories") public class ComplaintCategory {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String name; @Column(nullable=false) int slaHours; public Long getId(){return id;} public String getName(){return name;} public int getSlaHours(){return slaHours;} }
